function validate([prices, profits]) {
  const n = prices.length;
  if (n < 3 || n > 2000) return 'prices needs 3 to 2000 values.';
  if (profits.length !== n) return 'profits must be as long as prices.';
  if (prices.some(v => !Number.isInteger(v) || v < 1 || v > 1e6)) return 'Each price is an integer from 1 to 10^6.';
  if (profits.some(v => !Number.isInteger(v) || v < 1 || v > 1e6)) return 'Each profit is an integer from 1 to 10^6.';
  return null;
}

