function maxProfit(prices, profits) {
  const n = prices.length;
  let best = -1;

  for (let j = 1; j < n - 1; j++) {
    let left = 0;
    for (let i = 0; i < j; i++) {
      if (prices[i] < prices[j] && profits[i] > left) {
        left = profits[i];
      }
    }
    let right = 0;
    for (let k = j + 1; k < n; k++) {
      if (prices[k] > prices[j] && profits[k] > right) {
        right = profits[k];
      }
    }
    if (left > 0 && right > 0) {
      best = Math.max(best, left + profits[j] + right);
    }
  }
  return best;
}

