function maxProfit(prices, profits) {
  // Check every triple of indices directly.
  let answer = -1;
  const n = prices.length;
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++)
        if (prices[a] < prices[b] && prices[b] < prices[c]) answer = Math.max(answer, profits[a] + profits[b] + profits[c]);
  return answer;
}

