function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = 2000;
    const shape = rand();
    // Mostly random prices; sometimes prices only fall, so no triple exists and the answer is -1.
    const prices = Array.from({ length: n }, () => pick(1, 1e6));
    if (shape < 0.2) prices.sort((a, b) => b - a);
    const profits = Array.from({ length: n }, () => pick(1, 1e6));
    return [prices, profits];
  }
  // Small inputs use few distinct prices so ties and missing triples are common.
  const n = pick(3, 9);
  const top = [3, 5, 10][pick(0, 2)];
  const prices = Array.from({ length: n }, () => pick(1, top));
  const profits = Array.from({ length: n }, () => (rand() < 0.1 ? 1e6 : pick(1, 20)));
  return [prices, profits];
}
